-- Read-only postflight; every count must be zero. Does not certify IAM or HTTP.
SELECT 'invalid_budgets',COUNT(*) FROM formative_plan_version WHERE theory_planned_minutes NOT BETWEEN 1 AND 10000000 OR internship_planned_minutes NOT BETWEEN 0 AND 10000000
UNION ALL SELECT 'publication_dates',COUNT(*) FROM formative_plan_version WHERE status NOT IN ('Draft','Published') OR (status='Published' AND published_at_utc IS NULL) OR (status='Draft' AND published_at_utc IS NOT NULL)
UNION ALL SELECT 'published_totals',COUNT(*) FROM formative_plan_version v WHERE status='Published' AND theory_planned_minutes<>(SELECT COALESCE(SUM(m.planned_minutes),0) FROM formative_module m WHERE m.institution_id=v.institution_id AND m.version_id=v.id)
UNION ALL SELECT 'published_empty',COUNT(*) FROM formative_plan_version v WHERE status='Published' AND NOT EXISTS(SELECT 1 FROM formative_unit u WHERE u.institution_id=v.institution_id AND u.version_id=v.id)
UNION ALL SELECT 'published_missing_subject',COUNT(*) FROM formative_module m JOIN formative_plan_version v ON v.institution_id=m.institution_id AND v.id=m.version_id LEFT JOIN subject s ON s.institution_id=m.institution_id AND s.id=m.subject_id WHERE v.status='Published' AND s.id IS NULL
UNION ALL SELECT 'published_missing_outcomes',COUNT(*) FROM formative_module m JOIN formative_plan_version v ON v.institution_id=m.institution_id AND v.id=m.version_id WHERE v.status='Published' AND (NOT EXISTS(SELECT 1 FROM formative_module_competency c WHERE c.institution_id=m.institution_id AND c.module_id=m.id) OR NOT EXISTS(SELECT 1 FROM formative_module_content c WHERE c.institution_id=m.institution_id AND c.module_id=m.id))
UNION ALL SELECT 'invalid_bindings',COUNT(*) FROM course_edition_formative_plan b JOIN formative_plan_version v ON v.institution_id=b.institution_id AND v.id=b.version_id JOIN course_edition e ON e.institution_id=b.institution_id AND e.id=b.course_edition_id WHERE v.status<>'Published' OR v.study_path_id<>e.study_path_id OR v.study_path_id<>b.study_path_id
UNION ALL SELECT 'invalid_modules',COUNT(*) FROM formative_module WHERE planned_minutes NOT BETWEEN 1 AND 10000000 OR display_order<0
UNION ALL SELECT 'version_owner_mismatch',COUNT(*) FROM formative_plan_version v JOIN formative_plan p ON p.institution_id=v.institution_id AND p.id=v.plan_id WHERE v.study_path_id<>p.study_path_id
UNION ALL SELECT 'audit_version_mismatch',COUNT(*) FROM formative_plan_event e JOIN formative_plan_version v ON v.institution_id=e.institution_id AND v.id=e.version_id WHERE v.plan_id<>e.plan_id;
